        object result = cmd.ExecuteScalar();
        // ExecuteScalar 在結果集完全為空時回傳 null（非 COUNT 的情況）
        // COUNT(*) 即使 0 筆也會回傳 0，所以此例其實安全
        // 但若 SELECT 是其他欄位且無結果，才會回傳 null
        return result == null || result == DBNull.Value
            ? 0
            : (int)result;
    }
}

