// Login.aspx.cs — Forms Authentication 完整登入流程
protected void btnLogin_Click(object sender, EventArgs e)
{
    if (!Page.IsValid) return;

    string username = txtUsername.Text.Trim();
    string password = txtPassword.Text;

    // 查詢資料庫驗證（參數化，防 SQL Injection）
    bool valid = UserService.Validate(username, password);

    if (valid)
    {
        // 建立 Forms Auth Cookie
        FormsAuthentication.SetAuthCookie(
            username, chkRemember.Checked);

        // 跳轉到原本想存取的頁面（或預設頁）
        string redirect = FormsAuthentication
            .GetRedirectUrl(username, chkRemember.Checked);
        Response.Redirect(redirect);
    }
    else
    {
        lblError.Text = "帳號或密碼錯誤";
        // 安全：不告知是哪個錯誤
    }
}

