protected void btnPost_Click(object sender, EventArgs e)
{
    // HtmlEncode 將 < > & " 轉換為 HTML 實體，阻止 XSS
    string comment = Server.HtmlEncode(txtComment.Text);

    lblDisplay.Text = comment;  // Label.Text 設定純文字是安全的
    // 注意：若用 lblDisplay.Text = txtComment.Text（未編碼）也不安全

    // Response.Write 不會自動編碼，一定要手動處理
    Response.Write("<div>" +
        HttpUtility.HtmlEncode(txtComment.Text) + "</div>");
}
